CREATE OR REPLACE FUNCTION public.evidence_exists(_path text, _prefix text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _path LIKE _prefix||'/%' AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='jmg-documents' AND name=_path) $$;
REVOKE ALL ON FUNCTION public.evidence_exists(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.evidence_exists(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_budget_locked() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE st public.budget_status; BEGIN IF tg_table_name='budgets' THEN IF old.status IN ('aprovado','recusado') AND (to_jsonb(new)-ARRAY['archived','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['archived','updated_at','updated_by']) THEN RAISE EXCEPTION 'Orçamento bloqueado. Crie uma revisão.'; END IF; IF new.status='aprovado' AND (new.approval_date IS NULL OR NOT public.evidence_exists(new.approval_path,'approvals')) THEN RAISE EXCEPTION 'Informe data e comprovante de aprovação válido.'; END IF; RETURN new; END IF; IF TG_OP<>'INSERT' THEN SELECT status INTO st FROM public.budgets WHERE id=old.budget_id; IF st IN ('aprovado','recusado') THEN RAISE EXCEPTION 'Orçamento bloqueado. Crie uma revisão.'; END IF; END IF; IF TG_OP<>'DELETE' THEN SELECT status INTO st FROM public.budgets WHERE id=new.budget_id; IF st IN ('aprovado','recusado') THEN RAISE EXCEPTION 'Orçamento bloqueado. Crie uma revisão.'; END IF; END IF; RETURN coalesce(new,old); END $$;
CREATE OR REPLACE FUNCTION public.guard_contract() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND old.status='assinado' THEN RAISE EXCEPTION 'Contrato assinado preservado. Registre um aditivo.'; END IF; IF new.status IN ('gerado','assinado') AND (nullif(trim(new.body),'') IS NULL OR new.body ~ '\{\{[^}]+\}\}') THEN RAISE EXCEPTION 'Preencha todos os dados do contrato.'; END IF; IF new.status='assinado' AND (new.signed_date IS NULL OR NOT public.evidence_exists(new.signed_path,'contracts')) THEN RAISE EXCEPTION 'Anexe o contrato assinado e a data.'; END IF; RETURN new; END $$;
CREATE TRIGGER contract_insert_guard BEFORE INSERT ON public.contracts FOR EACH ROW EXECUTE FUNCTION public.guard_contract();
CREATE OR REPLACE FUNCTION public.guard_extra() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND old.approved THEN RAISE EXCEPTION 'Aditivo aprovado preservado. Registre outro aditivo.'; END IF; IF new.approved AND (new.approval_date IS NULL OR NOT public.evidence_exists(new.file_path,'extras')) THEN RAISE EXCEPTION 'Informe data e comprovante do aditivo.'; END IF; RETURN new; END $$;
CREATE UNIQUE INDEX financial_order_unique ON public.financial_entries(purchase_order_id) WHERE purchase_order_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.guard_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE total numeric; o public.purchase_orders; BEGIN IF TG_OP='UPDATE' THEN SELECT coalesce(sum(amount),0) INTO total FROM public.financial_settlements WHERE entry_id=old.id; IF new.amount<total OR (new.canceled AND total>0) OR (total>0 AND (new.work_id IS DISTINCT FROM old.work_id OR new.direction<>old.direction)) THEN RAISE EXCEPTION 'Lançamento com baixas não pode ser reduzido, cancelado ou reatribuído.'; END IF; END IF; IF new.purchase_order_id IS NOT NULL THEN SELECT * INTO o FROM public.purchase_orders WHERE id=new.purchase_order_id; IF new.direction<>'saida' OR new.work_id IS DISTINCT FROM o.work_id THEN RAISE EXCEPTION 'Compra deve ser uma saída da mesma obra.'; END IF; IF TG_OP='UPDATE' AND (new.amount<>old.amount OR new.purchase_order_id IS DISTINCT FROM old.purchase_order_id OR new.canceled<>old.canceled) THEN RAISE EXCEPTION 'Altere a compra pelo pedido.'; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER entry_guard BEFORE INSERT OR UPDATE ON public.financial_entries FOR EACH ROW EXECUTE FUNCTION public.guard_entry();
CREATE OR REPLACE FUNCTION public.guard_stage_dependency() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE dep public.work_stages; cycle boolean; BEGIN PERFORM id FROM public.works WHERE id=new.work_id FOR UPDATE; IF new.planned_end<new.planned_start OR new.actual_end<new.actual_start THEN RAISE EXCEPTION 'Término anterior ao início.'; END IF; IF new.dependency_id IS NOT NULL THEN SELECT * INTO dep FROM public.work_stages WHERE id=new.dependency_id; IF NOT FOUND OR dep.work_id<>new.work_id OR dep.id=new.id THEN RAISE EXCEPTION 'Dependência inválida.'; END IF; WITH RECURSIVE chain AS (SELECT id,dependency_id FROM public.work_stages WHERE id=new.dependency_id UNION SELECT s.id,s.dependency_id FROM public.work_stages s JOIN chain c ON s.id=c.dependency_id) SELECT exists(SELECT 1 FROM chain WHERE id=new.id) INTO cycle; IF cycle THEN RAISE EXCEPTION 'Dependência circular.'; END IF; IF new.planned_start<dep.planned_end THEN RAISE EXCEPTION 'Início previsto anterior ao término da dependência.'; END IF; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.create_purchase(_work_id uuid,_supplier_id uuid,_description text,_expected_date date,_lines jsonb,_due_date date) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE oid uuid; line jsonb; total numeric:=0; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF jsonb_array_length(_lines)=0 THEN RAISE EXCEPTION 'Adicione materiais.'; END IF; INSERT INTO public.purchase_orders(work_id,supplier_id,description,expected_date) VALUES(_work_id,_supplier_id,_description,_expected_date) RETURNING id INTO oid; FOR line IN SELECT * FROM jsonb_array_elements(_lines) LOOP IF line->>'side'<>'jmg' THEN RAISE EXCEPTION 'Material do cliente não gera compra da JMG.'; END IF; INSERT INTO public.purchase_lines(order_id,material_key,name,unit,quantity,unit_price) VALUES(oid,line->>'key',line->>'name',line->>'unit',(line->>'quantity')::numeric,(line->>'price')::numeric); total:=total+(line->>'quantity')::numeric*(line->>'price')::numeric; END LOOP; IF total<=0 THEN RAISE EXCEPTION 'Informe o valor da compra.'; END IF; INSERT INTO public.financial_entries(work_id,category,description,person_id,direction,amount,due_date,purchase_order_id) VALUES(_work_id,'Materiais',_description,_supplier_id,'saida',total,_due_date,oid); RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.create_purchase(uuid,uuid,text,date,jsonb,date) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_purchase(uuid,uuid,text,date,jsonb,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_purchase_line() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (to_jsonb(new)-'received') IS DISTINCT FROM (to_jsonb(old)-'received') THEN RAISE EXCEPTION 'Pedido preservado. Registre outro pedido.'; END IF; IF TG_OP='UPDATE' AND new.received<old.received THEN RAISE EXCEPTION 'Recebimento não pode ser reduzido.'; END IF; IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM public.financial_entries WHERE purchase_order_id=new.order_id) THEN RAISE EXCEPTION 'Pedido já finalizado.'; END IF; RETURN new; END $$;
CREATE TRIGGER purchase_line_guard BEFORE INSERT OR UPDATE ON public.purchase_lines FOR EACH ROW EXECUTE FUNCTION public.guard_purchase_line();
CREATE OR REPLACE FUNCTION public.receive_purchase(_line_id uuid,_quantity numeric) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE l public.purchase_lines; BEGIN SELECT * INTO l FROM public.purchase_lines WHERE id=_line_id FOR UPDATE; IF NOT FOUND OR _quantity<=0 THEN RAISE EXCEPTION 'Quantidade inválida.'; END IF; UPDATE public.purchase_lines SET received=received+_quantity WHERE id=l.id; UPDATE public.purchase_orders SET status=CASE WHEN EXISTS(SELECT 1 FROM public.purchase_lines WHERE order_id=l.order_id AND received<quantity) THEN 'parcial' ELSE 'recebido' END WHERE id=l.order_id; END $$;
REVOKE ALL ON FUNCTION public.receive_purchase(uuid,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.receive_purchase(uuid,numeric) TO authenticated;